create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'business_admin' check (role in ('super_admin','business_admin','analyst')), created_at timestamptz not null default now());
create table if not exists public.businesses (id uuid primary key default gen_random_uuid(), name text not null, owner_id uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.business_members (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('business_admin','analyst')), unique(business_id,user_id));
create table if not exists public.product_categories (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null);
create table if not exists public.products (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, category_id uuid references public.product_categories(id) on delete set null, name text not null, description text, sku text, price numeric(12,2), image_url text, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.customers (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, display_name text, email text, created_at timestamptz not null default now());
create table if not exists public.review_sources (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null, source_type text not null default 'manual');
create table if not exists public.reviews (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, customer_id uuid references public.customers(id) on delete set null, customer_name text, title text, content text not null, rating int not null check(rating between 1 and 5), source text not null default 'Website', external_id text, status text not null default 'published' check(status in ('pending','published','rejected')), created_at timestamptz not null default now());
create table if not exists public.sentiment_analyses (id uuid primary key default gen_random_uuid(), review_id uuid not null unique references public.reviews(id) on delete cascade, sentiment text not null check(sentiment in ('positive','negative','neutral','mixed')), confidence numeric(4,3), summary text, keywords jsonb not null default '[]', aspects jsonb not null default '[]', model_mode text not null, analyzed_at timestamptz not null default now());
create table if not exists public.review_aspects (id uuid primary key default gen_random_uuid(), review_id uuid not null references public.reviews(id) on delete cascade, aspect text not null, sentiment text not null, reason text);
create table if not exists public.extracted_keywords (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, product_id uuid references public.products(id) on delete cascade, keyword text not null, occurrences int not null default 1);
create table if not exists public.review_topics (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, product_id uuid references public.products(id) on delete cascade, topic text not null, sentiment text, review_count int not null default 0);
create table if not exists public.aggregated_insights (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, product_id uuid references public.products(id) on delete cascade, period_start date, period_end date, metrics jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.ai_summaries (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, product_id uuid references public.products(id) on delete cascade, summary text not null, strengths jsonb default '[]', weaknesses jsonb default '[]', recommendations jsonb default '[]', created_at timestamptz not null default now());
create table if not exists public.ai_conversations (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, user_id uuid references auth.users(id), messages jsonb not null default '[]', created_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, user_id uuid references auth.users(id), title text not null, body text, read_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.reports (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, created_by uuid references auth.users(id), name text not null, report_type text not null, filters jsonb default '{}', file_url text, created_at timestamptz not null default now());
create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(), business_id uuid references public.businesses(id) on delete cascade, actor_id uuid references auth.users(id), action text not null, entity_type text, entity_id uuid, metadata jsonb default '{}', created_at timestamptz not null default now());
create table if not exists public.import_jobs (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, created_by uuid references auth.users(id), filename text not null, status text not null default 'pending', total_rows int default 0, valid_rows int default 0, created_at timestamptz not null default now());
create table if not exists public.import_records (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.import_jobs(id) on delete cascade, row_number int not null, raw_data jsonb not null, error text);
create index if not exists reviews_business_created_idx on public.reviews(business_id,created_at desc);
create index if not exists reviews_product_idx on public.reviews(product_id);
create index if not exists products_business_idx on public.products(business_id);
create index if not exists analyses_sentiment_idx on public.sentiment_analyses(sentiment);
create or replace function public.is_business_member(target_business uuid) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.business_members where business_id=target_business and user_id=auth.uid()) or exists(select 1 from public.businesses where id=target_business and owner_id=auth.uid()); $$;
alter table public.profiles enable row level security; alter table public.businesses enable row level security; alter table public.business_members enable row level security; alter table public.products enable row level security; alter table public.product_categories enable row level security; alter table public.customers enable row level security; alter table public.reviews enable row level security; alter table public.sentiment_analyses enable row level security; alter table public.review_sources enable row level security; alter table public.review_aspects enable row level security; alter table public.extracted_keywords enable row level security; alter table public.review_topics enable row level security; alter table public.aggregated_insights enable row level security; alter table public.ai_summaries enable row level security; alter table public.ai_conversations enable row level security; alter table public.notifications enable row level security; alter table public.reports enable row level security; alter table public.audit_logs enable row level security; alter table public.import_jobs enable row level security; alter table public.import_records enable row level security;
create policy "profile self read" on public.profiles for select using(id=auth.uid()); create policy "profile self update" on public.profiles for update using(id=auth.uid());
create policy "business members read" on public.businesses for select using(owner_id=auth.uid() or public.is_business_member(id)); create policy "owner create business" on public.businesses for insert with check(owner_id=auth.uid());
create policy "members read own memberships" on public.business_members for select using(user_id=auth.uid() or public.is_business_member(business_id));
create policy "members read products" on public.products for select using(public.is_business_member(business_id)); create policy "members manage products" on public.products for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id));
create policy "members manage categories" on public.product_categories for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id));
create policy "members manage customers" on public.customers for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id));
create policy "members read reviews" on public.reviews for select using(public.is_business_member(business_id)); create policy "members manage reviews" on public.reviews for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id));
create policy "members manage analyses" on public.sentiment_analyses for all using(exists(select 1 from public.reviews r where r.id=review_id and public.is_business_member(r.business_id))) with check(exists(select 1 from public.reviews r where r.id=review_id and public.is_business_member(r.business_id)));
create policy "members manage review sources" on public.review_sources for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id));
create policy "members manage aspects" on public.review_aspects for all using(exists(select 1 from public.reviews r where r.id=review_id and public.is_business_member(r.business_id))) with check(exists(select 1 from public.reviews r where r.id=review_id and public.is_business_member(r.business_id)));
create policy "members manage keywords" on public.extracted_keywords for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id)); create policy "members manage topics" on public.review_topics for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id)); create policy "members manage insights" on public.aggregated_insights for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id)); create policy "members manage summaries" on public.ai_summaries for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id)); create policy "members manage conversations" on public.ai_conversations for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id)); create policy "members manage notifications" on public.notifications for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id)); create policy "members manage reports" on public.reports for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id)); create policy "members read audit logs" on public.audit_logs for select using(public.is_business_member(business_id)); create policy "members manage import jobs" on public.import_jobs for all using(public.is_business_member(business_id)) with check(public.is_business_member(business_id)); create policy "members manage import records" on public.import_records for all using(exists(select 1 from public.import_jobs j where j.id=job_id and public.is_business_member(j.business_id))) with check(exists(select 1 from public.import_jobs j where j.id=job_id and public.is_business_member(j.business_id)));
